package main
import("bytes";"crypto/sha256";"encoding/binary";"encoding/hex";"encoding/json";"errors";"flag";"fmt";"os";"os/exec";"runtime";"sort";"time")
const schema="forge.acc56.u25.nativego.v1"
const tasks=64
const budget=64
const repetitions=64
var seeds=[]uint64{106101,106103,106107,106109,106111}
var families=[]string{"AFFINE","QUADRATIC","CONSTANT","NOISY"}
var arms=[]string{"UNIFORM","LENGTH","ERROR_FIRST","LEVIN"}
func mix(x uint64)uint64{x+=0x9e3779b97f4a7c15;x=(x^(x>>30))*0xbf58476d1ce4e5b9;x=(x^(x>>27))*0x94d049bb133111eb;return x^(x>>31)}
type program struct{Kind int;A,B int64;Text string;Ops int}
func grammar()[]program{p:=[]program{{Kind:0,Text:"x",Ops:0}};for a:=-3;a<=3;a++{p=append(p,program{Kind:1,A:int64(a),Text:fmt.Sprintf("%d",a),Ops:0},program{Kind:2,A:int64(a),Text:fmt.Sprintf("(x+%d)",a),Ops:1},program{Kind:3,A:int64(a),Text:fmt.Sprintf("(x*%d)",a),Ops:1})};for a:=-3;a<=3;a++{for b:=-3;b<=3;b++{p=append(p,program{Kind:4,A:int64(a),B:int64(b),Text:fmt.Sprintf("((x+%d)*%d)",a,b),Ops:2},program{Kind:5,A:int64(a),B:int64(b),Text:fmt.Sprintf("((x*%d)+%d)",a,b),Ops:2},program{Kind:6,A:int64(a),B:int64(b),Text:fmt.Sprintf("((x+%d)*(x+%d))",a,b),Ops:3})}};sort.Slice(p,func(i,j int)bool{return p[i].Text<p[j].Text});return p}
func eval(p program,x uint64)uint64{a,b:=uint64(p.A),uint64(p.B);switch p.Kind{case 0:return x;case 1:return a;case 2:return x+a;case 3:return x*a;case 4:return(x+a)*b;case 5:return x*a+b;case 6:return(x+a)*(x+b)};panic("kind")}
func target(seed uint64,task int,family string)program{a:=int64(int(mix(seed^uint64(task)*0x71cf0bd3)%7)-3);b:=int64(int(mix(seed^uint64(task)*0xbf58476d1ce4e5b9)%7)-3);switch family{case "CONSTANT":return program{Kind:1,A:a};case "QUADRATIC":return program{Kind:6,A:a,B:b};case "NOISY":return program{Kind:5,A:a,B:b};default:return program{Kind:4,A:a,B:b}}}
func xAt(seed uint64,task,j int,test bool)uint64{h:=mix(seed^uint64(task)*0xa0761d6478bd642f^uint64(j)*0xe7037ed1a0b428db);if test{return 100+h%257};return uint64(int64(-40+int64(h%81)))}
func put(h interface{Write([]byte)(int,error)},v uint64){var b[8]byte;binary.LittleEndian.PutUint64(b[:],v);h.Write(b[:])}
func order(p []program,mode string)[]int{ii:=make([]int,len(p));for i:=range ii{ii[i]=i};sort.SliceStable(ii,func(i,j int)bool{a,b:=p[ii[i]],p[ii[j]];switch mode{case "LENGTH":if len(a.Text)!=len(b.Text){return len(a.Text)<len(b.Text)};case "ERROR_FIRST":if a.Ops!=b.Ops{return a.Ops<b.Ops};case "LEVIN":ca,cb:=len(a.Text),len(b.Text);if ca>16{ca=16};if cb>16{cb=16};wa,wb:=(1<<uint(ca))*(a.Ops+1),(1<<uint(cb))*(b.Ops+1);if wa!=wb{return wa<wb}};return a.Text<b.Text});return ii}
type worker struct{Schema,Family,Arm,InputSHA256,TruthSHA256,PredictionSHA256,SelectedSHA256 string;Seed uint64;Tasks,TrainPoints,TestPoints,Candidates,EvaluatedPerTask,Evaluations,EvaluationReplications,CorrectHeldout,CorrectTrain int;PeakRSSBytes uint64;HeldoutAccuracy float64}
func work(arm,family string,seed uint64)(worker,error){var z worker;ok:=false;for _,x:=range arms{if x==arm{ok=true}};if !ok{return z,errors.New("arm")};ok=false;for _,x:=range families{if x==family{ok=true}};if !ok{return z,errors.New("family")}
 pp:=grammar();indices:=order(pp,arm);src,truth,pred,selected:=sha256.New(),sha256.New(),sha256.New(),sha256.New();good,trainGood,evaluations:=0,0,0
 for task:=0;task<tasks;task++{ans:=target(seed,task,family);var xs,ys [12]uint64;for j:=0;j<12;j++{x:=xAt(seed,task,j,false);y:=eval(ans,x);if family=="NOISY"&&j%8==0{y++};xs[j],ys[j]=x,y;put(src,x);put(src,y)}
 var xx,yy [32]uint64;for j:=0;j<32;j++{xx[j]=xAt(seed,task,j,true);yy[j]=eval(ans,xx[j]);put(src,xx[j]);put(truth,xx[j]);put(truth,yy[j])}
 best:=-1;bestError:=13;bestLen:=int(^uint(0)>>1);bestText:=""
 for rank:=0;rank<budget;rank++{p:=pp[indices[rank]];mismatch:=0
  for rep:=0;rep<repetitions;rep++{for j,x:=range xs{v:=eval(p,x);evaluations++;if rep==0&&v!=ys[j]{mismatch++}}}
  if best<0||mismatch<bestError||mismatch==bestError&&(len(p.Text)<bestLen||len(p.Text)==bestLen&&p.Text<bestText){best=indices[rank];bestError=mismatch;bestLen=len(p.Text);bestText=p.Text}
 }
 if best<0{return z,errors.New("missing candidate")}
 chosen:=pp[best];for _,c:=range []byte(chosen.Text){put(selected,uint64(c))};put(selected,uint64(len(chosen.Text)))
 for j,x:=range xs{if eval(chosen,x)==ys[j]{trainGood++}}
 for j,x:=range xx{v:=eval(chosen,x);put(pred,x);put(pred,v);if v==yy[j]{good++}}
 }
 rss,e:=peakResidentBytes();if e!=nil{return z,e};if rss==0{return z,errors.New("RSS unavailable")}
 return worker{Schema:schema,Family:family,Arm:arm,Seed:seed,Tasks:tasks,TrainPoints:tasks*12,TestPoints:tasks*32,Candidates:len(pp),EvaluatedPerTask:budget,Evaluations:evaluations,EvaluationReplications:repetitions,CorrectHeldout:good,CorrectTrain:trainGood,PeakRSSBytes:rss,HeldoutAccuracy:float64(good)/float64(tasks*32),InputSHA256:hex.EncodeToString(src.Sum(nil)),TruthSHA256:hex.EncodeToString(truth.Sum(nil)),PredictionSHA256:hex.EncodeToString(pred.Sum(nil)),SelectedSHA256:hex.EncodeToString(selected.Sum(nil))},nil
}
type trial struct{Worker worker;CPUSeconds,WallSeconds float64}
type cohort struct{Family,Fastest string;Accuracy,CPU,RSS map[string]float64;AccuracyGain,CPURatio,RSSRatio float64;Improved,Regressed bool}
type report struct{Schema,OS,Classification string;NativeChildCount int;ScientificFirstUse,NativeModelAcceleration bool;Trials []trial;Cohorts []cohort}
func median(x []float64)float64{a:=append([]float64(nil),x...);sort.Float64s(a);return a[len(a)/2]}
func child(exe,arm,family string,seed uint64)(trial,error){var t trial;c:=exec.Command(exe,"-worker","-arm",arm,"-family",family,"-seed",fmt.Sprint(seed));var o,e bytes.Buffer;c.Stdout=&o;c.Stderr=&e;start:=time.Now();err:=c.Run();wall:=time.Since(start).Seconds();if err!=nil{return t,fmt.Errorf("%s/%s: %w %s",arm,family,err,e.String())};if c.ProcessState==nil{return t,errors.New("missing process")};cpu:=(c.ProcessState.UserTime()+c.ProcessState.SystemTime()).Seconds();if cpu<=0||wall<=0{return t,errors.New("zero CPU/wall")};var w worker;if err=json.Unmarshal(o.Bytes(),&w);err!=nil{return t,err};if w.Schema!=schema||w.Arm!=arm||w.Family!=family||w.Seed!=seed||w.Tasks!=tasks||w.Candidates!=169||w.EvaluatedPerTask!=budget||w.EvaluationReplications!=repetitions||w.Evaluations!=tasks*budget*12*repetitions||w.PeakRSSBytes==0{return t,errors.New("invalid worker")};return trial{Worker:w,CPUSeconds:cpu,WallSeconds:wall},nil}
func compare(rows []trial,family string)(cohort,error){c:=cohort{Family:family,Accuracy:map[string]float64{},CPU:map[string]float64{},RSS:map[string]float64{}};groups:=map[string][]trial{};paired:=map[uint64]string{};for _,r:=range rows{w:=r.Worker;if w.Family!=family{continue};groups[w.Arm]=append(groups[w.Arm],r);sig:=w.InputSHA256+"/"+w.TruthSHA256;if v,ok:=paired[w.Seed];ok&&v!=sig{return c,errors.New("source drift")};paired[w.Seed]=sig};if len(paired)!=5{return c,errors.New("missing seed")};for _,m:=range arms{a:=groups[m];if len(a)!=5{return c,errors.New("missing arm")};var accuracy,cpu,rss []float64;for _,r:=range a{accuracy=append(accuracy,r.Worker.HeldoutAccuracy);cpu=append(cpu,r.CPUSeconds);rss=append(rss,float64(r.Worker.PeakRSSBytes))};c.Accuracy[m]=median(accuracy);c.CPU[m]=median(cpu);c.RSS[m]=median(rss)}
 c.Fastest="UNIFORM";highest:=c.Accuracy["UNIFORM"];for _,m:=range []string{"LENGTH","ERROR_FIRST"}{if c.CPU[m]<c.CPU[c.Fastest]{c.Fastest=m};if c.Accuracy[m]>highest{highest=c.Accuracy[m]}};c.AccuracyGain=c.Accuracy["LEVIN"]-highest;c.CPURatio=c.CPU["LEVIN"]/c.CPU[c.Fastest];c.RSSRatio=c.RSS["LEVIN"]/c.RSS[c.Fastest];c.Improved=c.AccuracyGain>=.05;c.Regressed=c.AccuracyGain< -0.02;return c,nil}
func drive(path string)error{exe,e:=os.Executable();if e!=nil{return e};r:=report{Schema:schema,OS:runtime.GOOS,Trials:make([]trial,0,80)};for _,family:=range families{for i,seed:=range seeds{order:=[]string{"UNIFORM","LENGTH","ERROR_FIRST","LEVIN"};if i%2==1{order=[]string{"LEVIN","ERROR_FIRST","LENGTH","UNIFORM"}};for _,arm:=range order{t,e:=child(exe,arm,family,seed);if e!=nil{return e};r.Trials=append(r.Trials,t)}};c,e:=compare(r.Trials,family);if e!=nil{return e};r.Cohorts=append(r.Cohorts,c)};r.NativeChildCount=len(r.Trials);if r.NativeChildCount!=80{return errors.New("incomplete workers")};improved,pass:=0,true;for _,c:=range r.Cohorts{if c.Improved{improved++};if c.Regressed||c.CPURatio>1.10||c.RSSRatio>1.10{pass=false}};r.Classification="U25_NO_GENERAL_VERIFIED_NATIVE_GO_LEARNING_WIN";if pass&&improved>=2{r.Classification="U25_RESTRICTED_SYNTHETIC_GO_LEARNING_POSITIVE_ONLY"};b,e:=json.MarshalIndent(r,"","  ");if e!=nil{return e};if e=os.WriteFile(path,append(b,10),0644);e!=nil{return e};fmt.Println("ACC56_U25_NATIVE_CHILDREN_80_PASS");fmt.Println("ACC56_U25_CLASSIFICATION="+r.Classification);return nil}
func main(){w:=flag.Bool("worker",false,"");arm:=flag.String("arm","LEVIN","");family:=flag.String("family","AFFINE","");seed:=flag.Uint64("seed",106101,"");out:=flag.String("out","acc56-report.json","");flag.Parse();var e error;if *w{var v worker;v,e=work(*arm,*family,*seed);if e==nil{e=json.NewEncoder(os.Stdout).Encode(v)}}else{e=drive(*out)};if e!=nil{fmt.Fprintln(os.Stderr,"ACC56_U25_BLOCKED:",e);os.Exit(1)}}
